// One query per automation, scoped by trigger_type. Deliberately does NOT
// exclude entities that already have automation_runs history — the "wait"
// action type needs an entity to be reconsidered on a LATER poll after a
// wait step has been logged, so per-entity dedup can no longer happen at
// the SQL level (a one-shot "seen before? skip forever" anti-join). All
// dedup/wait-elapsed logic now lives in Evaluate & Expand Actions instead,
// using the sibling Look Up Existing Runs node's data. This does mean
// every matching entity gets re-evaluated every poll even once fully
// done — acceptable at this app's data volume; automation_runs itself is
// still the source of truth for "has this exact action already run".
//
// Automation metadata (trigger_config/condition_tree) travels along as a
// jsonb literal column rather than relying on cross-node pairedItem
// lookups, since automationId here is our own integer PK (not user
// input) it's safe to inline into the query text. `actions` is
// DELIBERATELY excluded from this literal — it holds the raw,
// not-yet-personalized email templates (e.g. "Hi {{first_name}}"), and
// this literal flows through Run Candidate Query's Query field, which
// is an n8n expression template (`={{ $json.sqlQuery }}`). n8n's
// expression engine treats ANY "{{ }}" it finds as ITS OWN syntax, so a
// merge token embedded in that string gets misread as an (invalid) n8n
// expression and silently renders as "undefined" — this is exactly the
// bug that caused live sends to say "Hi undefined". Evaluate & Expand
// Actions re-attaches the real `actions` (with intact merge tokens) by
// reading Select Active Automations' own output directly — plain data
// access in a Code node, never passed through an expression field.
// Task and Calendar both read from `activities` (see src/types/event.ts)
// — there is no separate calendar_events table in this schema.
//
// Every branch selects a consistent set of merge-token columns
// (phone/job_title/lead_status/city/state/country/company_name/owner_*)
// so the same AUTOMATION_DYNAMIC_FIELDS token set works regardless of
// trigger type — a token whose column doesn't apply to a given branch
// (e.g. {{deal_value}} on a Contact trigger) just comes back NULL and
// fill() renders it as an empty string, same fallback every other
// inapplicable token already had. stage_entered_at/last_contacted_at
// back the days_since_stage_entered/days_since_last_activity trigger
// fields (computed in getFieldValue, not here).
const output = [];
for (const item of $input.all()) {
const row = item.json; // { id, trigger_type, trigger_config, condition_tree, actions }
const meta = JSON.stringify({
  automationId: row.id,
  entityType: row.trigger_type,
  triggerConfig: row.trigger_config,
  conditionTree: row.condition_tree,
});
const metaLiteral = `'${meta.replace(/'/g, "''")}'::jsonb`;
const id = row.id;

// owner_name/owner_email/owner_phone resolve the {{owner_*}} merge tokens
// — contacts/companies use their own owner_id, opportunities use
// assigned_user, and tasks/calendar events (both `activities` rows) use
// the assigned user_id.
const queries = {
  contact: `SELECT c.id, c.first_name, c.last_name, c.email, c.phone, c.job_title, c.lead_status, c.birthdate, c.city, c.state, c.zip_code, c.country, c.last_contacted_at, c.lead_source, c.do_not_contact, c.dnc_sms, c.created_at, c.updated_at, c.email_logs, c.unsubscribe_token,
      c.id AS contact_id, c.city AS contact_city, c.state AS contact_state, c.zip_code AS contact_zip_code, c.country AS contact_country,
      comp.name AS company_name, comp.id AS company_id, comp.street_address AS company_street_address, comp.zip_code AS company_zip_code,
      comp.phone AS company_phone, comp.website AS company_website, comp.city AS company_city, comp.state AS company_state, comp.country AS company_country, comp.updated_at AS company_updated_at,
      ow.name AS owner_name, ow.email AS owner_email, ow.phone AS owner_phone, ow.id AS owner_user_id,
      (SELECT COALESCE(json_agg(t.name), '[]'::json) FROM tags t JOIN taggables tg ON tg.tag_id = t.id WHERE tg.entity_type = 'contact' AND tg.entity_id = c.id) AS tags,
      ${metaLiteral} AS automation_meta,
      (SELECT company_name FROM company_profile LIMIT 1) AS our_company_name
    FROM contacts c
    LEFT JOIN companies comp ON comp.id = c.account_id
    LEFT JOIN users ow ON ow.id = c.owner_id
    WHERE c.is_archived = false;`,
  company: `SELECT co.id, co.name, NULL::text AS first_name, NULL::text AS last_name, NULL::text AS email, NULL::text AS phone, NULL::text AS job_title, NULL::text AS lead_status,
      co.name AS company_name, co.industry, co.website,
      co.id AS company_id, co.street_address AS company_street_address, co.zip_code AS company_zip_code, co.phone AS company_phone, co.website AS company_website,
      co.city AS company_city, co.state AS company_state, co.country AS company_country, co.updated_at AS company_updated_at,
      ow.name AS owner_name, ow.email AS owner_email, ow.phone AS owner_phone, ow.id AS owner_user_id,
      co.account_status, co.city, co.state, co.country, co.annual_revenue, co.employee_count, co.account_health, co.tier, co.created_at,
      (SELECT COALESCE(json_agg(t.name), '[]'::json) FROM tags t JOIN taggables tg ON tg.tag_id = t.id WHERE tg.entity_type = 'company' AND tg.entity_id = co.id) AS tags,
      ${metaLiteral} AS automation_meta,
      (SELECT company_name FROM company_profile LIMIT 1) AS our_company_name
    FROM companies co
    LEFT JOIN users ow ON ow.id = co.owner_id
    WHERE co.is_archived = false;`,
  task: `SELECT act.id, act.subject AS name, ct.first_name, ct.last_name, ct.email, ct.phone, ct.dnc_sms, ct.job_title, ct.lead_status,
      ct.id AS contact_id, ct.city AS contact_city, ct.state AS contact_state, ct.zip_code AS contact_zip_code, ct.country AS contact_country,
      ct.birthdate AS contact_birthdate, ct.lead_source AS contact_lead_source, ct.created_at AS contact_created_at, ct.updated_at AS contact_updated_at,
      comp.name AS company_name, comp.id AS company_id, comp.street_address AS company_street_address, comp.zip_code AS company_zip_code,
      comp.phone AS company_phone, comp.website AS company_website, comp.city AS company_city, comp.state AS company_state, comp.country AS company_country, comp.updated_at AS company_updated_at,
      ow.name AS owner_name, ow.email AS owner_email, ow.phone AS owner_phone, ow.id AS owner_user_id,
      act.is_completed, act.due_at, act.type AS event_type, act.start_at, act.end_at, act.location, act.body AS notes,
      ct.unsubscribe_token,
      (SELECT COALESCE(json_agg(t.name), '[]'::json) FROM tags t JOIN taggables tg ON tg.tag_id = t.id WHERE tg.entity_type = 'contact' AND tg.entity_id = ct.id) AS tags,
      ${metaLiteral} AS automation_meta,
      (SELECT company_name FROM company_profile LIMIT 1) AS our_company_name
    FROM activities act
    LEFT JOIN contacts ct ON ct.id = act.contact_id
    LEFT JOIN companies comp ON comp.id = ct.account_id
    LEFT JOIN users ow ON ow.id = act.user_id
    WHERE act.due_at IS NOT NULL AND (ct.id IS NULL OR ct.is_archived = false);`,
  calendar: `SELECT act.id, act.subject AS name, ct.first_name, ct.last_name, ct.email, ct.phone, ct.dnc_sms, ct.job_title, ct.lead_status,
      ct.id AS contact_id, ct.city AS contact_city, ct.state AS contact_state, ct.zip_code AS contact_zip_code, ct.country AS contact_country,
      ct.birthdate AS contact_birthdate, ct.lead_source AS contact_lead_source, ct.created_at AS contact_created_at, ct.updated_at AS contact_updated_at,
      comp.name AS company_name, comp.id AS company_id, comp.street_address AS company_street_address, comp.zip_code AS company_zip_code,
      comp.phone AS company_phone, comp.website AS company_website, comp.city AS company_city, comp.state AS company_state, comp.country AS company_country, comp.updated_at AS company_updated_at,
      ow.name AS owner_name, ow.email AS owner_email, ow.phone AS owner_phone, ow.id AS owner_user_id,
      act.type AS event_type, act.due_at, act.is_completed, act.start_at, act.end_at, act.location, act.body AS notes, act.is_reschedule,
      ct.unsubscribe_token,
      (SELECT COALESCE(json_agg(t.name), '[]'::json) FROM tags t JOIN taggables tg ON tg.tag_id = t.id WHERE tg.entity_type = 'contact' AND tg.entity_id = ct.id) AS tags,
      ${metaLiteral} AS automation_meta,
      (SELECT company_name FROM company_profile LIMIT 1) AS our_company_name
    FROM activities act
    LEFT JOIN contacts ct ON ct.id = act.contact_id
    LEFT JOIN companies comp ON comp.id = ct.account_id
    LEFT JOIN users ow ON ow.id = act.user_id
    WHERE act.due_at IS NOT NULL AND (ct.id IS NULL OR ct.is_archived = false);`,
  ticket: `SELECT t.id, t.subject AS name, t.status, t.priority, t.sla_due_at, t.created_at, t.resolved_at,
      ct.first_name, ct.last_name, ct.email, ct.phone, ct.dnc_sms, ct.job_title, ct.lead_status,
      ct.id AS contact_id, ct.city AS contact_city, ct.state AS contact_state, ct.zip_code AS contact_zip_code, ct.country AS contact_country,
      ct.birthdate AS contact_birthdate, ct.lead_source AS contact_lead_source, ct.created_at AS contact_created_at, ct.updated_at AS contact_updated_at,
      co.name AS company_name, co.id AS company_id, co.street_address AS company_street_address, co.zip_code AS company_zip_code,
      co.phone AS company_phone, co.website AS company_website, co.city AS company_city, co.state AS company_state, co.country AS company_country, co.updated_at AS company_updated_at,
      ow.name AS owner_name, ow.email AS owner_email, ow.phone AS owner_phone, ow.id AS owner_user_id,
      ct.unsubscribe_token,
      (SELECT COALESCE(json_agg(t.name), '[]'::json) FROM tags t JOIN taggables tg ON tg.tag_id = t.id WHERE tg.entity_type = 'contact' AND tg.entity_id = ct.id) AS tags,
      ${metaLiteral} AS automation_meta,
      (SELECT company_name FROM company_profile LIMIT 1) AS our_company_name
    FROM tickets t
    LEFT JOIN contacts ct ON ct.id = t.contact_id
    LEFT JOIN companies co ON co.id = t.account_id
    LEFT JOIN users ow ON ow.id = t.assigned_user
    WHERE t.is_archived = false AND (ct.id IS NULL OR ct.is_archived = false);`,
  pipeline: `SELECT o.id, o.name, o.account_id, o.deal_value, o.expected_close, o.source, o.priority, o.stage_entered_at,
      o.status, o.probability, o.lost_reason, o.created_at, o.updated_at,
      GREATEST(o.updated_at, COALESCE(la.last_activity, o.updated_at)) AS last_touched_at,
      ct.first_name, ct.last_name, ct.email, ct.phone, ct.dnc_sms, ct.job_title, ct.lead_status, ct.city, ct.state, ct.country,
      ct.id AS contact_id, ct.city AS contact_city, ct.state AS contact_state, ct.zip_code AS contact_zip_code, ct.country AS contact_country,
      ct.birthdate AS contact_birthdate, ct.lead_source AS contact_lead_source, ct.created_at AS contact_created_at, ct.updated_at AS contact_updated_at,
      co.name AS company_name, co.industry, co.website,
      co.id AS company_id, co.street_address AS company_street_address, co.zip_code AS company_zip_code, co.phone AS company_phone, co.website AS company_website,
      co.city AS company_city, co.state AS company_state, co.country AS company_country, co.updated_at AS company_updated_at,
      ow.name AS owner_name, ow.email AS owner_email, ow.phone AS owner_phone, ow.id AS owner_user_id,
      o.pipeline_id, o.stage_id, st.name AS stage_name, pl.name AS pipeline_name,
      prop.id AS proposal_id, prop.public_token AS proposal_token, prop.status AS proposal_status, prop.emailed_at AS proposal_emailed_at, prop.viewed_at AS proposal_viewed_at,
      contr.id AS contract_id, contr.public_token AS contract_token, contr.status AS contract_status, contr.sent_at AS contract_sent_at, contr.signed_at AS contract_signed_at,
      ct.unsubscribe_token,
      (SELECT COALESCE(json_agg(t.name), '[]'::json) FROM tags t JOIN taggables tg ON tg.tag_id = t.id WHERE tg.entity_type = 'contact' AND tg.entity_id = ct.id) AS tags,
      ${metaLiteral} AS automation_meta,
      (SELECT company_name FROM company_profile LIMIT 1) AS our_company_name,
      appt.activity_id, appt.due_at, appt.start_at, appt.end_at, appt.location,
      appt.appointment_subject, appt.activity_is_completed
    FROM opportunities o
    LEFT JOIN contacts ct ON ct.id = o.contact_id
    LEFT JOIN companies co ON co.id = o.account_id
    LEFT JOIN users ow ON ow.id = o.assigned_user
    LEFT JOIN stages st ON st.id = o.stage_id
    LEFT JOIN pipelines pl ON pl.id = o.pipeline_id
    LEFT JOIN (SELECT opportunity_id, MAX(created_at) AS last_activity FROM activities GROUP BY opportunity_id) la ON la.opportunity_id = o.id
    LEFT JOIN LATERAL (
      SELECT p.id, p.public_token, p.status, p.emailed_at, p.viewed_at FROM proposals p WHERE p.opportunity_id = o.id ORDER BY p.created_at DESC LIMIT 1
    ) prop ON true
    LEFT JOIN LATERAL (
      SELECT c2.id, c2.public_token, c2.status, c2.sent_at, c2.signed_at FROM contracts c2 WHERE c2.opportunity_id = o.id ORDER BY c2.created_at DESC LIMIT 1
    ) contr ON true
    LEFT JOIN LATERAL (
      SELECT a.id AS activity_id, a.due_at, a.start_at, a.end_at, a.location, a.subject AS appointment_subject, a.is_completed AS activity_is_completed
      FROM activities a WHERE a.opportunity_id = o.id AND a.type = 'meeting'
      ORDER BY a.is_completed ASC, a.due_at DESC LIMIT 1
    ) appt ON true
    WHERE o.is_archived = false AND (ct.id IS NULL OR ct.is_archived = false);`,
};

const sqlQuery = queries[row.trigger_type];
if (!sqlQuery) continue;
output.push({ json: { sqlQuery, automationId: id } });
}
return output;

function getFieldValue(row, field) {
  if (field === 'age') {
    if (!row.birthdate) return null;
    const ms = Date.now() - new Date(row.birthdate).getTime();
    return Math.floor(ms / (365.25 * 24 * 3600 * 1000));
  }
  if (field === 'overdue') {
    return !row.is_completed && row.due_at && new Date(row.due_at) < new Date();
  }
  if (field === 'location') {
    return [row.city, row.state, row.country].filter(Boolean).join(', ');
  }
  if (field === 'days_since_stage_entered') {
    if (!row.stage_entered_at) return null;
    return Math.floor((Date.now() - new Date(row.stage_entered_at).getTime()) / 86400000);
  }
  if (field === 'days_since_last_activity') {
    if (!row.last_contacted_at) return null;
    return Math.floor((Date.now() - new Date(row.last_contacted_at).getTime()) / 86400000);
  }
  if (field === 'days_since_created') {
    if (!row.created_at) return null;
    return Math.floor((Date.now() - new Date(row.created_at).getTime()) / 86400000);
  }
  if (field === 'days_inactive') {
    if (!row.last_touched_at) return null;
    return Math.floor((Date.now() - new Date(row.last_touched_at).getTime()) / 86400000);
  }
  if (field === 'sla_overdue') {
    if (!row.sla_due_at || row.status === 'resolved' || row.status === 'closed') return false;
    return new Date(row.sla_due_at).getTime() < Date.now();
  }
  // Backed by contacts.email_logs — 'received' entries come from a live
  // Gmail-inbox poller (contacts-email-reply.json) that runs regardless of
  // which flow sent the original email, so replies are always accurate.
  // 'sent' entries only get an opened_at once the tracking pixel embedded
  // in that HTML email is actually loaded — many email clients block
  // remote images by default, so this is a best-effort signal, not a
  // guarantee an unopened result means truly unread.
  if (field === 'email_replied') {
    const logs = Array.isArray(row.email_logs) ? row.email_logs : [];
    const lastSent = logs.filter((l) => l && l.type === 'sent').sort((a, b) => new Date(b.sent_at) - new Date(a.sent_at))[0];
    const referenceTime = lastSent ? new Date(lastSent.sent_at).getTime() : 0;
    return logs.some((l) => l && l.type === 'received' && new Date(l.sent_at).getTime() > referenceTime);
  }
  if (field === 'email_opened') {
    const logs = Array.isArray(row.email_logs) ? row.email_logs : [];
    return logs.some((l) => l && l.type === 'sent' && l.opened_at);
  }
  if (field === 'days_since_proposal_sent') {
    if (!row.proposal_emailed_at) return null;
    return Math.floor((Date.now() - new Date(row.proposal_emailed_at).getTime()) / 86400000);
  }
  if (field === 'days_since_proposal_viewed') {
    if (!row.proposal_viewed_at) return null;
    return Math.floor((Date.now() - new Date(row.proposal_viewed_at).getTime()) / 86400000);
  }
  if (field === 'days_since_contract_sent') {
    if (!row.contract_sent_at) return null;
    return Math.floor((Date.now() - new Date(row.contract_sent_at).getTime()) / 86400000);
  }
  if (field === 'days_since_contract_signed') {
    if (!row.contract_signed_at) return null;
    return Math.floor((Date.now() - new Date(row.contract_signed_at).getTime()) / 86400000);
  }
  return row[field];
}

function evalCondition(row, cond) {
  if (!cond || !cond.field) return true;
  const actual = getFieldValue(row, cond.field);
  const expected = cond.value;
  switch (cond.operator) {
    case 'equals': return Array.isArray(actual) ? actual.includes(expected) : String(actual) === String(expected);
    case 'not_equals': return Array.isArray(actual) ? !actual.includes(expected) : String(actual) !== String(expected);
    case 'contains': return String(actual || '').toLowerCase().includes(String(expected).toLowerCase());
    case 'greater_than': { const n = Number(actual); return Number.isFinite(n) ? n > Number(expected) : new Date(actual) > new Date(expected); }
    case 'less_than': { const n = Number(actual); return Number.isFinite(n) ? n < Number(expected) : new Date(actual) < new Date(expected); }
    case 'is_true': return Boolean(actual) === true;
    case 'is_false': return Boolean(actual) === false;
    default: return false;
  }
}

// A "wait" action's duration, in milliseconds.
function waitMs(config) {
  const amount = Number(config?.amount) || 0;
  const perUnit = { minutes: 60 * 1000, hours: 3600 * 1000, days: 86400 * 1000, months: 30 * 86400 * 1000 };
  return amount * (perUnit[config?.unit] || perUnit.days);
}

const actionsByAutomationId = {};
const createdByAutomationId = {};
for (const it of $('Select Active Automations').all()) {
  actionsByAutomationId[it.json.id] = it.json.actions;
  createdByAutomationId[it.json.id] = it.json.created_by;
}

const runsByKey = {};
for (const it of $('Look Up Existing Runs').all()) {
  const r = it.json;
  if (r.action_id == null) continue; // alwaysOutputData placeholder from a zero-row lookup
  runsByKey[`${r.action_id}|${r.entity_type}|${r.entity_id}`] = r;
}

// A condition can now appear ANYWHERE in an automation's step sequence,
// not just once right after the trigger — 'condition' is just another
// automation_actions row (action_type: 'condition', action_config the
// same {field,operator,value} shape trigger_config always used). Every
// other row can be nested under a condition via parent_step_key (pointing
// at that condition's own step_key); `branch` on a nested row says which
// side of THAT specific condition it's on ('true'/'false'). Root-level
// rows keep parent_step_key null and branch 'default' — unchanged from
// before this feature existed, so old flat (non-nested) automations still
// work with zero migration beyond the one-time backfill that gave every
// existing row step_key = id.
//
// walk() is a depth-first traversal that collects every currently-due
// step across the whole tree into `out`, recursing into whichever branch
// a condition currently evaluates to — recomputed fresh on every poll,
// same as the old single-condition behavior, just generalized to any
// depth (a flapping condition can make different runs descend into
// different branches; already-logged automation_runs from an earlier
// branch are simply left as harmless history, exactly like the old
// single-branch model already did). It stops the ENTIRE remaining walk
// the instant it hits a wait that isn't satisfied yet, since nothing
// sequenced after an in-progress wait — even across a later sibling
// condition — should fire before that wait clears.
//
// actions come from Select Active Automations' own output (plain data
// access, not a `={{ }}` expression field) rather than from the SQL
// literal, so raw merge tokens like {{first_name}} survive intact — see
// the comment on Build Candidate Query for why.
function walk(steps, allActions, row, entityType, out) {
  for (const step of steps) {
    if (step.action_type === 'condition') {
      const branch = evalCondition(row, step.action_config) ? 'true' : 'false';
      const children = allActions
        .filter((a) => a.parent_step_key === step.step_key && a.branch === branch)
        .slice()
        .sort((a, b) => a.sort_order - b.sort_order);
      if (walk(children, allActions, row, entityType, out)) return true; // a wait blocked further progress inside this branch
      continue; // finished that subtree — move on to the next sibling after the condition
    }

    const key = `${step.id}|${entityType}|${row.id}`;
    const existingRun = runsByKey[key];
    if (existingRun && existingRun.status !== 'error') {
      if (step.action_type === 'wait') {
        const elapsed = Date.now() - new Date(existingRun.ran_at).getTime();
        if (elapsed < waitMs(step.action_config)) return true; // still waiting — stop the whole walk here
        continue; // wait satisfied — move on to the next step
      }
      continue; // already ran (tag/email/etc.) — never re-run, move on
    }

    // Not yet logged — this is due to run now.
    out.push(step);
    // A freshly-started wait blocks everything sequenced after it THIS
    // pass, anywhere in the tree — the next step only becomes eligible
    // once the wait's logged ran_at is old enough, checked on a later poll.
    if (step.action_type === 'wait') return true;
  }
  return false;
}

const output = [];
$input.all().forEach((item, itemIndex) => {
  const row = item.json;
  const meta = row.automation_meta;
  if (!meta) return;
  if (!evalCondition(row, meta.triggerConfig)) return;

  const allActions = actionsByAutomationId[meta.automationId] || [];
  const rootSteps = allActions
    .filter((a) => a.parent_step_key == null && a.branch === 'default')
    .slice()
    .sort((a, b) => a.sort_order - b.sort_order);

  const dueSteps = [];
  walk(rootSteps, allActions, row, meta.entityType, dueSteps);

  for (const action of dueSteps) {
    output.push({
      json: {
        automationId: meta.automationId,
        actionId: action.id,
        entityType: meta.entityType,
        entityId: row.id,
        branch: action.branch,
        action,
        row,
        createdBy: createdByAutomationId[meta.automationId],
      },
      pairedItem: { item: itemIndex },
    });
  }
});
return output;

// $env access can be blocked entirely by the n8n instance's own security settings (N8N_BLOCK_ENV_ACCESS_IN_NODE) — reading a blocked var THROWS rather than returning undefined, so a bare `$env.X || ''` never gets a chance to fall back.
function safeEnv(key) { try { return $env[key] || ''; } catch (e) { return ''; } }
const meta = $input.item.json;
const ourCompanyName = (meta.row && meta.row.our_company_name) || '';
const row = meta.row;
if (!row.email) {
  return [{ json: { automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch, status: 'error', detail: 'No email address available for this record.', hasEmail: false, senderName: ourCompanyName } }];
}

// Data arrives however a rep typed it (or a CSV import had it) —
// mirrors src/utils/text.ts's toTitleCase so merge fields don't send
// 'Hi pretty' for a name stored all-lowercase.
function toTitleCase(s) {
  return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' ');
}
function money(n) {
  return n != null && n !== '' ? '$' + Number(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '';
}
function dateStr(d) {
  return d ? new Date(d).toLocaleDateString() : '';
}
function dateTimeStr(d) {
  return d ? new Date(d).toLocaleString() : '';
}
// Reads like a person wrote it — "Monday, Sep 21 at 1:00 PM" — for the
// one merge field (appointment.start_time) that shows up in a sentence a
// contact actually reads, rather than a raw locale timestamp.
function dateTimePretty(d) {
  if (!d) return '';
  const dt = new Date(d);
  const datePart = dt.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' });
