// This node was confirmed (via a real execution) to run ONCE TOTAL per
// poll, not once per item, despite having no explicit `mode` set — when
// two update_field actions became due in the same poll for the first
// time (see automation "09 Proposal Approved"), only the first item's
// update ever ran; the second was silently dropped until the next poll
// retried it fresh. Iterating $input.all() and returning one result per
// item fixes this for any number of simultaneous update_field actions.
return $input.all().map((item) => {
const meta = item.json; // {automationId, actionId, entityType, entityId, branch, action, row, createdBy}
const config = meta.action.action_config || {};

// Allowlist only — the field/table/column never come from raw user
// input, they're looked up through this map, so there's no way an
// automation's saved config can point an UPDATE at an arbitrary column.
const FIELD_MAP = {
  contact: {
    lead_status: { table: 'contacts', column: 'lead_status', valueType: 'text' },
    owner_id: { table: 'contacts', column: 'owner_id', valueType: 'int' },
  },
  company: {
    account_status: { table: 'companies', column: 'account_status', valueType: 'text' },
    account_health: { table: 'companies', column: 'account_health', valueType: 'text' },
    tier: { table: 'companies', column: 'tier', valueType: 'text' },
    owner_id: { table: 'companies', column: 'owner_id', valueType: 'int' },
  },
  pipeline: {
    status: { table: 'opportunities', column: 'status', valueType: 'text' },
    stage_id: { table: 'opportunities', column: 'stage_id', valueType: 'int', extra: ', stage_entered_at = now()' },
    priority: { table: 'opportunities', column: 'priority', valueType: 'text' },
    assigned_user: { table: 'opportunities', column: 'assigned_user', valueType: 'int' },
    // Lead status lives on the CONTACT, not the deal — same
    // pipeline->contact redirect already used for tags (see
    // Insert Taggable/Delete Taggable), since DealCard.tsx and
    // the contact record are what actually show lead_status.
    lead_status: { table: 'contacts', column: 'lead_status', valueType: 'text', targetContactId: true },
  },
  task: {
    is_completed: { table: 'activities', column: 'is_completed', valueType: 'boolean' },
    user_id: { table: 'activities', column: 'user_id', valueType: 'int' },
  },
  calendar: {
    is_completed: { table: 'activities', column: 'is_completed', valueType: 'boolean' },
    user_id: { table: 'activities', column: 'user_id', valueType: 'int' },
  },
  ticket: {
    status: { table: 'tickets', column: 'status', valueType: 'text' },
    priority: { table: 'tickets', column: 'priority', valueType: 'text' },
    assigned_user: { table: 'tickets', column: 'assigned_user', valueType: 'int' },
  },
};

// contacts/companies/opportunities all have updated_at; activities does not.
const UPDATED_AT_TABLES = new Set(['contacts', 'companies', 'opportunities', 'tickets']);

function fail(detail) {
  return { json: { automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch, status: 'error', detail } };
}

const spec = (FIELD_MAP[meta.entityType] || {})[config.field];
if (!spec) return fail(`Field "${config.field}" is not updatable for entity type "${meta.entityType}".`);
if (config.value === undefined || config.value === null || config.value === '') return fail('No value configured for this update.');

let castedValue = config.value;
if (spec.valueType === 'int') {
  castedValue = parseInt(config.value, 10);
  if (!Number.isInteger(castedValue)) return fail(`Value "${config.value}" is not a valid id.`);
} else if (spec.valueType === 'boolean') {
  castedValue = config.value === true || config.value === 'true';
}

// Marking a task/calendar item complete (or un-complete) via automation
// should behave the same as doing it by hand — stamp/clear completed_at.
const completedAtExtra = spec.column === 'is_completed' ? ', completed_at = CASE WHEN $1::boolean THEN now() ELSE NULL END' : '';
const updatedAtExtra = UPDATED_AT_TABLES.has(spec.table) ? ', updated_at = now()' : '';

const sqlQuery = `UPDATE ${spec.table} SET ${spec.column} = $1${completedAtExtra}${spec.extra || ''}${updatedAtExtra} WHERE id = $2 RETURNING id;`;
const targetId = spec.targetContactId ? meta.row.contact_id : meta.entityId;
if (spec.targetContactId && !targetId) return fail('This deal has no linked contact to update.');

return {
  json: {
    automationId: meta.automationId,
    actionId: meta.actionId,
    entityType: meta.entityType,
    entityId: meta.entityId,
    branch: meta.branch,
    status: 'ok',
    sqlQuery,
    params: [castedValue, targetId],
  },
};
});

// Same fix as Prepare Update Field — this node also runs once total
// rather than once per item, so cross-node .item (no index) always
// resolved to the FIRST item regardless of how many update_field
// actions were actually due this poll. itemMatching(index) resolves
// the correct paired item for each one (Postgres nodes preserve
// pairedItem 1:1 automatically).
return $input.all().map((_, index) => {
  const meta = $('Prepare Update Field').itemMatching(index).json;
  return { json: { automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch, status: 'success', detail: null } };
});

// Look Up Existing Runs' item count/pairedItem lineage is no longer
// 1:1 with Build Candidate Query's items (it now fetches the full
// existing-run history for every currently-active automation, for
// dedup purposes, decoupled from whichever candidate-query item
// triggered it) — relying on itemMatching(index) against it caused a
// real 'Multiple matches' crash. This node's only real job is to hand
// Build Candidate Query's items back unchanged for Run Candidate
// Query, so read them directly instead of walking through Look Up
// Existing Runs' unrelated item shape.
return $('Build Candidate Query').all().map((item) => ({ json: item.json }));

function toTitleCase(s) { return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' '); }
// A smaller merge-token set than Prepare Email's — these are short,
// plain-text lines (a task subject, a DM, an SMS), not full HTML emails.
function fill(template, row) {
  return (template || '')
    .replace(/{{\s*first_name\s*}}/gi, toTitleCase(row.first_name) || '')
    .replace(/{{\s*last_name\s*}}/gi, toTitleCase(row.last_name) || '')
    .replace(/{{\s*deal_name\s*}}/gi, row.name || '')
    .replace(/{{\s*lost_reason\s*}}/gi, row.lost_reason || '')
    .replace(/{{\s*stage_name\s*}}/gi, row.stage_name || '')
    .replace(/{{\s*company_name\s*}}/gi, row.our_company_name || '');
}
const meta = $input.item.json; // {automationId, actionId, entityType, entityId, branch, action, row, createdBy}
const row = meta.row;
const config = meta.action.action_config || {};

const contactId = meta.entityType === 'contact' ? row.id : (row.contact_id ?? null);
const opportunityId = meta.entityType === 'pipeline' ? row.id : null;
const companyId = meta.entityType === 'company' ? row.id : null;
const ownerUserId = row.owner_user_id ?? null;
const priority = ['Low', 'Medium', 'High'].includes(config.priority) ? config.priority : 'Low';
const subject = fill(config.subject, row) || 'Follow up';

return [{
  json: {
    automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch,
    contactId, opportunityId, companyId, ownerUserId, subject, priority,
  },
}];

