const meta = $input.item.json;
const row = meta.row;
const config = meta.action.action_config || {};
const phone = row.phone || null;
const dncSms = row.dnc_sms === true;
const canSend = !!phone && !dncSms;

return [{
  json: {
    automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch,
    phone, canSend, text: fill(config.message, row),
  },
