const meta = $input.item.json;
const row = meta.row || {};
function toTitleCase(s) { return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' '); }
function money(n) { return n != null && n !== '' ? '$' + Number(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : ''; }

const raw = (meta.action.action_config && meta.action.action_config.lost_reason) || '';
const resolvedLostReason = raw
  .replace(/{{\s*contact\.first_name\s*}}/gi, toTitleCase(row.first_name))
  .replace(/{{\s*contact\.last_name\s*}}/gi, toTitleCase(row.last_name))
  .replace(/{{\s*contact\.full_name\s*}}/gi, toTitleCase(`${row.first_name || ''} ${row.last_name || ''}`.trim()))
  .replace(/{{\s*contact\.email\s*}}/gi, row.email || '')
  .replace(/{{\s*company\.name\s*}}/gi, row.company_name || '')
  .replace(/{{\s*opportunity\.name\s*}}/gi, row.name || '')
  .replace(/{{\s*opportunity\.value\s*}}/gi, money(row.deal_value))
  .replace(/{{\s*opportunity\.stage\s*}}/gi, row.stage_name || '')
  .replace(/{{\s*user\.full_name\s*}}/gi, toTitleCase(row.owner_name))
  .replace(/{{[^{}]*}}/g, '')
  .trim();
