// UPDATE fail outright when a resolved token makes this longer than a rep
// would have guessed from the raw text they typed.
const truncatedLostReason = resolvedLostReason.length > 50 ? resolvedLostReason.slice(0, 49) + '\u2026' : resolvedLostReason;

return [{ json: { ...meta, resolvedLostReason: truncatedLostReason || null } }];
